class Solution {
    public int uniquePaths(int m, int n) {
        int[] dp = new int[n];
        // 初始全1 第一行
        for (int j = 0; j < n; j++) {
            dp[j] = 1;
        }
        // 逐行更新
        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                dp[j] = dp[j] + dp[j - 1];
            }
        }
        return dp[n - 1];
    }
}
